INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1054136-coe203', 'stk-iiiii', 'COE 203', 'info', '{"desc": "جودة المقرر بشكل عام: جيد جداً\nالمواضيع التي يغطيها المقرر: تطبيق على الـ 202 + استخدام الـ fpga وبعض لغات البرمجه المستخدمه للهاردوير وتصميم دوائر رقميه على البورد وباستخدام الـ fpga …\nالكتاب المستخدم للمقرر: مافيه كتاب … فيه لاب مانيوال ونوت …\nالأسئلة والأمثلة المستخدمة في المقرر: الكورس عباره عن لاب تطبيقي فـ الامثله التطبيقيه كثير …\nمدى فائدته في الناحية التطبيقية: مهم ومفيد وتطبيقي للـ 202…\n\nالماده عباره عن ساعه وحده خفيفه وتطبيقيه للـ 202 وفيها مقمده عن الـ fpga ولغات البرمجه للهاردوير …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coe-203-digital-logic-laboratory/120813/2", "user": "IIIII", "ts": 1339421089000, "tid": 120813, "pn": 2}}', 1339421089000, 1794826849, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1437989-coe203', 'stk-cs_scientist', 'COE 203', 'info', '{"desc": "بالبداية بأنوّه على شيئين، الـCo-requisite للمادة ذي اللي هي 202، بس مع هذا أقترح إن الطالب ياخذ ذي المادة بالترم اللي بعد 202 إذا كان ما يأثر على جدوله و مواده، لأن المادة فيها أشياء كثيرة ممكن تلخبط فيها لأن بعض المواضيع تاخذها باللاب قبل الليكتشر، فـ ممكن يجي اللاب و يخلص و أنت مو فاهم شيء لأن ما أخذته بالليكتشر و بالنسبة لي كان شرح مدرس اللاب ماش مو ذاك الشيء الكويس، لو قدرت تاخذها بعد 202 يكون كويس\n\nجودة المقرر بشكل عام\n\nالمادة تطبيق عملي للـCOE202، مادة حلوة و الشغل فيها جميل\n\nالمواضيع التي يغطيها المقرر\n\nتقريبًا كل مواضيع 202 بس بشكل عملي على برنامج في أجهزتهم حق التصميم الرقمي + FPGA Boards\n\nالكتاب المستخدم للمقرر\n\nكل اسبوع قبل اللاب يرفعون اللاب مانوال على البلاك بورد\n\nالأسئلة والأمثلة المستخدمة في المقرر\n\nما فيه أي أسئلة ولا اختبارات ولا شيء، بس كان فيه لاب بروجيكت نهاية الترم، ترم 151\nعلى كلام مشرفين اللاب المنهج كل شوي يطورونه، فـ ممكن الترم الجاي ولا اللي بعده يكون ترتيب الدروس غير أو حاذفين البروجيكت، الله أعلم\nالمادة وضعها مو مستقر للحين\n\nمدى فائدته في الناحية التطبيقية\n\nتطبيق مهم للـ202 اللي تعتبر مادة أساسية مهمة\n\nبس بأنوّه على شيء، ترا المادة درجاتها Standard، يعني A+ من 95 و كل خمس درجات قريد، بس مو صعبة ترا، الواحد يقدر يجيب فيها A بالراحة\n\nA+ عاد لازم تكون أحرص بالتجربة و تسلم ريبورتات كويسة", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coe-203-digital-logic-laboratory/120813/4", "user": "CS_Scientist", "ts": 1451906901000, "tid": 120813, "pn": 4}}', 1451906901000, 1794826849, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1484131-coe203', 'stk-krooom', 'COE 203', 'info', '{"desc": "161 مع 202\nجودة المقرر بشكل عام\n\nالمادة تطبيق عملي للـCOE202، مادة حلوة و الشغل فيها جميل\n\nالمواضيع التي يغطيها المقرر\n\nتقريبًا كل مواضيع 202 بس بشكل عملي على برنامج في أجهزتهم حق التصميم الرقمي + FPGA Boards لكن البداية قد تكون صعبة لانه verilog تعتبر لغة غريبة شوي\n\nالكتاب المستخدم للمقرر\n\nكل اسبوع قبل اللاب يرفعون اللاب مانوال على البلاك بورد\n\nالأسئلة والأمثلة المستخدمة في المقرر\n\nما فيه أي أسئلة ولا اختبارات ولا شيء، بس كان فيه لاب بروجيكت نهاية الترم، ترم 161\n\nمدى فائدته في الناحية التطبيقية\n\nتطبيق مهم للـ202 اللي تعتبر مادة أساسية مهمة\n\nبس بأنوّه على شيء، ترا المادة درجاتها Standard، يعني A+ من 95 و كل خمس درجات قريد، بس مو صعبة ترا، الواحد يقدر يجيب فيها A بالراحة\n\nA+ عاد لازم تكون أحرص بالتجربة و تسلم ريبورتات كويسة\n\nوحاول تاخذها بعد 202 لانني عانيت فيها", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coe-203-digital-logic-laboratory/120813/6", "user": "Krooom", "ts": 1512203817000, "tid": 120813, "pn": 6}}', 1512203817000, 1794826849, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p517805-coe203', 'stk-barhomitto', 'COE 203', 'srcU', '{"html": "ايوه تكفى ياليت تفيدني لأني كذا حاس انه سهل<br>وبعدين هو يبغاه على verilog أو schematic<br>أي شي<br><br>​<span data-fid=\"stk-f517805-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f517805-0": {"name": "project091.doc", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/786aea48aba726fe0820818431cbc0ab0477e8c7c7018285c920ec0c9f6c36db"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coe-203/81856/3", "user": "Barhomitto", "ts": 1262788421000, "tid": 81856, "pn": 3}}', 1262788421000, 1794826849, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ad0rs-coe203', 'stk-ad0rs', 'COE 203', 'doc', '{"docs": [{"id": "stk-dr-f98322", "n": "Dr. Masud-Ul-Hasan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Coe203 t141\n\nلتحضير :\nبداية كل لاب\nطريقة الشرح :\nياخذ نص ساعة تقريبا من بداية اللاب يشرح فيها التجربة وابن أمك تسأله بعدين عن حاجة شرحها قبل\nالقريد النهائي:\nD\nالصوت:\nواضح\nإضافات :\nاللاب عند باقي الدكاترة يخلص في ساعة ساعتين\nعند الدكتور ذا كنا أحيانا نحضر سكشن ثاني عشان نكمل تجربة الاسبوع!!\nيدقق على استخدام البرنامج xilinx اكثر من ال objective حقت اللاب", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1440106-coe203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-masud-ul-hasan/98322/6", "user": "ad0rs", "ts": 1453411637000, "tid": 98322, "pn": 6}}]}', 1453411637000, 1794826849, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8697-coe203', 'stk-user8697', 'COE 203', 'doc', '{"docs": [{"id": "stk-dr-f98325", "n": "Dr. Zubair Baig", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخذت معاه coe203\n\nالتحضير :\n\nكل يووم وما اتوقعه يركز عالتاخير\n\nطريقة الشرح :\n\nشرح سريع ما كنت اركز معاه صراحة 😛\nلكن لو واجهت مشكلة متساعد جدا\n\nالكويزات :\n\nمافيش\n\nالمياجر:\n\nمافيش\n\nالفاينلات :\n\nمافيش\n\nالقريد النهائي:\n\nA+\n\nالصوت:\n\nكنت اجلس قريب منه وكان واضح\n\nإضافات :\n\nاسهل لاب مر علي في حياتي … الشعب كله درجاته فوق 95 … ببساطة أحسن دكتور لاب في العالم", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1370376-coe203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-zubair-baig/98325/19", "user": "user8697", "ts": 1400925896000, "tid": 98325, "pn": 19}}]}', 1400925896000, 1794826849, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-cs_scientist-coe203', 'stk-cs_scientist', 'COE 203', 'doc', '{"docs": [{"id": "stk-dr-f115388", "n": "Dr. Masudul Hasan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "COE203-151\n\nالتحضير : بداية اللاب، ما يحط ليت و يحضرك، بس بيقولك فوّت كثير من الشرح، يسمح بالميك أب\n\nطريقة الشرح : فهمه للمادة ممتاز و يشرحلك الكونسبتس و كذا، بس برنامج Verilog ما يعرفله واجد، كان يهنّق كثير\nبس المساعد اللي معه كان فاهم و يساعدنا شوي\n\nالكويزات : ما فيه كويزات\n\nالمياجر: ما فيه مياجر\n\nالفاينلات : ما فيه فاينل\n\nالصوت: يجيب النوم شوي، بس ينسمع و ينفهم\n\nإضافات :\nالدكتور مشكلته إنه مو فاهم للـVerilog كثير، و هذا سبب لنا مشكلة لأن حنا منزلين المادة و مو عارفين للـVerilog بعد\nعطانا لاب بروجيكت نهاية الترم، كان لحسة شوي، بس قدرنا نسويه، لازم تكون فاهم بالـVerilog عشان تسويه\n\nالقريد النهائي: C+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1437979-coe203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-masudul-hasan/115388/7", "user": "CS_Scientist", "ts": 1451903412000, "tid": 115388, "pn": 7}}]}', 1451903412000, 1794826849, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
